const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=localStorage.getItem('lamma-language')||'ar',user=null,orders=[],stats={},cursor=null,view='active',mode='login',area='',mailMode='local';
const t=(ar,en)=>lang==='ar'?ar:en,fmt=n=>Number(n||0).toLocaleString(lang==='ar'?'ar-EG':'en-GB',{maximumFractionDigits:2});
const field=(label,input)=>`<label>${label}${input}</label>`;
const input=(name,type='text',extra='')=>`<input name="${name}" type="${type}" ${extra}>`;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,5000)}
async function api(path,data){let r;try{r=await fetch('/api'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Lamma-Request':'1','Accept-Language':lang},body:data===undefined?undefined:JSON.stringify(data)})}catch{throw Error(t('تعذر الاتصال بالخادم','Cannot reach server'))}const b=await r.json();if(!r.ok){if(r.status===401&&user){user=null;render()}throw Error(b.error)}return b}
async function run(button,fn){if(button)button.disabled=true;try{await fn()}catch(e){toast(e.message)}finally{if(button)button.disabled=false}}
async function refresh(append=false){const q=new URLSearchParams({view,area,limit:'30'});if(append&&cursor)q.set('before',cursor);const [list,summary,me]=await Promise.all([api('/orders?'+q),api('/stats'),api('/me')]);orders=append?orders.concat(list.orders):list.orders;cursor=list.next_cursor;stats=summary;user=me.user;render()}
function publicPage(){return `<div class="authgrid"><div><span class="eyebrow">${t('كل مشوار يبدأ بلَمّة','Every collection starts with Lamma')}</span><h2>${t('مكانك في اللَمّة','A place in the circle')}</h2><p class="small">${t('صاحب محل؟ أضف الكرتون الجاهز للاستلام. جامع كرتون؟ احجز طلبات مناسبة لمشوارك.','Own a shop? List your cardboard. Collect cardboard? Find pickups for your next round.')}</p></div><form class="panel" id="auth"><h3>${mode==='register'?t('إنشاء حساب','Create account'):mode==='forgot'?t('استعادة كلمة المرور','Password recovery'):t('تسجيل الدخول','Sign in')}</h3>${mode==='register'?field(t('اسمك / اسم المحل','Your name / shop name'),input('name','text','required minlength="2" maxlength="60" autocomplete="name"'))+field(t('نوع الحساب','Account type'),`<select name="role"><option value="shop">${t('صاحب محل','Shop owner')}</option><option value="collector">${t('جامع كرتون','Collector')}</option></select>`):''}${field(t('البريد الإلكتروني','Email'),input('email','email','required maxlength="200" autocomplete="email" dir="ltr"'))}${mode!=='forgot'?field(t('كلمة المرور (10 أحرف على الأقل)','Password (at least 10 characters)'),input('password','password',`required minlength="10" maxlength="128" autocomplete="${mode==='register'?'new-password':'current-password'}" dir="ltr"`)):''}<button class="full">${mode==='register'?t('إنشاء الحساب','Create account'):mode==='forgot'?t('إرسال رابط الاستعادة','Send recovery link'):t('دخول','Sign in')}</button><div class="actions"><button type="button" class="ghost" data-mode="${mode==='login'?'register':'login'}">${mode==='login'?t('إنشاء حساب جديد','Create account'):t('العودة للدخول','Back to sign in')}</button>${mode==='login'?`<button type="button" class="ghost" data-mode="forgot">${t('نسيت كلمة المرور؟','Forgot password?')}</button>`:''}</div></form></div>`}
function card(o){const status={new:t('متاح للجمع','Available'),booked:t('محجوز','Booked'),pending:t('بانتظار تأكيد المحل','Awaiting shop confirmation'),done:t('استلام مؤكد','Confirmed'),cancelled:t('ملغي','Cancelled')};let actions='';const btn=(action,label)=>`<button data-action="${action}" data-id="${o.id}">${label}</button>`;if(user.role==='shop'){if(o.status==='new')actions=btn('cancel',t('إلغاء الطلب','Cancel'));if(o.status==='pending')actions=btn('confirm',t('تأكيد الوزن والسعر','Confirm weight & price'))+btn('reject',t('إرجاع للتصحيح','Return for correction'))}else{if(o.status==='new')actions=btn('book',t('حجز الاستلام','Book pickup'));if(o.collector_id===user.id&&o.status==='booked')actions=btn('receipt',t('تسجيل الاستلام','Record pickup'))+btn('release',t('تحرير الطلب','Release'))}return `<article class="card"><div class="cardhead"><div><span class="small">#${o.id}</span><h3>${esc(o.name)}</h3></div><span class="badge ${o.status}">${status[o.status]}</span></div><p>${esc(o.area)} · ${o.period==='am'?t('صباحًا','Morning'):t('مساءً','Evening')}</p>${o.address?`<p class="address">⌖ ${esc(o.address)}</p>${o.lat!=null?`<button class="ghost" data-map="${o.id}">${t('عرض نقطة الاستلام على الخريطة','View pickup on map')}</button>`:''}`:`<p class="small">${t('العنوان التفصيلي يظهر بعد الحجز.','Exact address is visible after booking.')}</p>`}<div class="weight">${fmt(o.weight)} <small>${t('كجم تقريبي','kg estimated')}</small></div>${o.actual!=null?`<div class="receipt">${t('الوزن الفعلي','Actual weight')}: ${fmt(o.actual)} ${t('كجم','kg')} · ${t('سعر الكيلو','Price/kg')}: ${fmt(o.price)} ${t('ج.م','EGP')}<br>${t('الإجمالي','Total')}: <b>${fmt(o.actual*o.price)} ${t('ج.م','EGP')}</b></div>`:''}<div class="actions">${actions}</div></article>`}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('لَمّة — للكرتون قيمة','Lamma — Cardboard has value');$('#brand').textContent=t('◈ لَمّة','◈ Lamma');$('#tagline').textContent=t('للكرتون قيمة. وللمشوار حساب.','Value in cardboard. Purpose in every trip.');$('#language').textContent=lang==='ar'?'English':'العربية';$('#language').onclick=()=>{lang=lang==='ar'?'en':'ar';localStorage.setItem('lamma-language',lang);render()};$('#hero').hidden=!!user;$('#hero-copy').innerHTML=`<span class="eyebrow">${t('من كرتون متفرق… لقيمة متجمعة','Small pickups. Shared value.')}</span><h1>${t('جولة واحدة.<br><em>قيمة أكبر.</em>','One round.<br><em>More value.</em>')}</h1><p>${t('وصّل كرتون محلك بجامع قريب. طلب واضح، واستلام باتفاق.','Connect your shop to a collector. Clear requests. Confirmed pickups.')}</p><a class="cta" href="#workspace">${t('ابدأ مع لَمّة ←','Start with Lamma →')}</a>`;$('#notice').textContent=t('تشغيل محلي • لا تتم مدفوعات عبر المنصة • بياناتك محفوظة على هذا الجهاز.','Local installation • No payments are processed • Data is stored on this computer.');$('#footer').textContent=t('لَمّة / نقيس الاستلام المؤكد، ولا نفترض حدوث التدوير.','Lamma / We measure confirmed pickups, not assumed recycling.');$('#account').innerHTML=user?`<span>${esc(user.name)}</span><button class="ghost" id="logout">${t('خروج','Sign out')}</button>`:'';
if(!user){$('#content').innerHTML=publicPage();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});$('#auth').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('/'+mode,Object.fromEntries(new FormData(e.target)));if(mode==='forgot'){toast(t('لو البريد مسجل، اتجهز رابط الاستعادة.','If the email is registered, a recovery link has been prepared.'));return}const me=await api('/me');user=me.user;mailMode=me.mail_mode;view='active';await refresh()})};return}
$('#logout').onclick=e=>run(e.target,async()=>{await api('/logout',{});user=null;orders=[];render()});$('#content').innerHTML=`${!user.verified?`<div class="verify panel"><h3>${t('أكد بريدك قبل إضافة أو حجز الطلبات','Verify your email before creating or booking requests')}</h3><p>${mailMode==='local'?t('البريد في الوضع المحلي: رابط التأكيد موجود في صندوق التطوير على جهازك. افتح ملف START-HERE لمعرفة طريقة عرضه.','Local mail mode: find the verification link in the development mailbox on your computer. See START-HERE for instructions.'):t('راجع بريدك للحصول على رابط التأكيد.','Check your inbox for a verification link.')}</p><button id="resend">${t('إرسال رابط جديد','Send a new link')}</button><button class="ghost" id="checkverified">${t('أكدت البريد — تحديث','Verified — refresh')}</button></div>`:''}<div class="sectionhead"><div><span class="eyebrow">${user.role==='shop'?t('مساحة المحل','Shop workspace'):t('مساحة الجامع','Collector workspace')}</span><h2>${t('أهلًا، ','Hello, ')}${esc(user.name)}</h2></div><div class="actions"><button class="ghost" id="refresh">${t('تحديث ↻','Refresh ↻')}</button><button class="ghost" id="logout-all">${t('خروج من كل الأجهزة','Sign out everywhere')}</button></div></div><div class="stats compact"><div class="stat">${t('طلباتك النشطة','Your active requests')}<strong>${fmt(stats.active)}</strong></div><div class="stat">${t('استلام مؤكد / كجم','Confirmed / kg')}<strong>${fmt(stats.weight)}</strong></div><div class="stat">${t('قيمة المعاملات / ج.م','Transaction value / EGP')}<strong>${fmt(stats.value)}</strong></div></div><div class="grid dashboard"><aside>${user.role==='shop'?`<form class="panel" id="add"><h3>${t('عندك كرتون جاهز؟','Ready for pickup?')}</h3>${field(t('المنطقة','Area'),input('area','text','required minlength="2" maxlength="80"'))}${field(t('العنوان التفصيلي','Full address'),input('address','text','required minlength="5" maxlength="300"'))}<p class="small">${t('العنوان والإحداثيات يظهروا للجامع بعد الحجز فقط.','Address and coordinates are visible to the assigned collector only.')}</p><details><summary>${t('نقطة الخريطة (اختياري)','Map location (optional)')}</summary>${field(t('خط العرض','Latitude'),input('lat','number','min="-90" max="90" step="any"'))}${field(t('خط الطول','Longitude'),input('lng','number','min="-180" max="180" step="any"'))}<button type="button" class="ghost" id="locate">${t('استخدم موقعي الحالي','Use my current location')}</button><p class="small">${t('سيطلب المتصفح إذن الموقع. راجع الإحداثيات قبل الحفظ.','Your browser will ask for location access. Check coordinates before saving.')}</p></details>${field(t('الوزن التقريبي / كجم','Estimated weight / kg'),input('weight','number','required min="1" max="5000" step="0.1"'))}${field(t('الفترة','Period'),`<select name="period"><option value="am">${t('صباحًا','Morning')}</option><option value="pm">${t('مساءً','Evening')}</option></select>`)}<button class="full" ${!user.verified?'disabled':''}>${t('إضافة طلب +','Add request +')}</button></form>`:`<div class="panel"><h3>${t('جهز مشوارك','Plan your round')}</h3><p class="small">${t('احجز الطلب المناسب، وسجل الوزن والسعر بعد الاستلام. المحل يراجع ويؤكد.','Book suitable requests. Record weight and price after pickup. The shop reviews and confirms.')}</p></div>`}</aside><div><form class="row search" id="search">${input('area','search',`value="${esc(area)}" placeholder="${t('بحث بالمنطقة','Search area')}" aria-label="${t('بحث بالمنطقة','Search area')}" maxlength="80"`)}<button>${t('بحث','Search')}</button></form><nav class="tabs"><button data-view="active" class="${view==='active'?'active':''}">${t('الطلبات النشطة','Active requests')}</button><button data-view="history" class="${view==='history'?'active':''}">${t('السجل','History')}</button></nav><div class="cards">${orders.map(card).join('')||`<div class="empty">${t('لا توجد طلبات هنا بعد.','No requests here yet.')}</div>`}</div>${cursor?`<button class="ghost full" id="more">${t('تحميل المزيد','Load more')}</button>`:''}</div></div>`;
$('#refresh').onclick=e=>run(e.target,()=>refresh());$('#logout-all').onclick=e=>run(e.target,async()=>{await api('/logout-all',{});user=null;render()});if($('#resend')){$('#resend').onclick=e=>run(e.target,async()=>{await api('/resend',{});toast(t('تم تجهيز رابط جديد','A new link has been prepared'))});$('#checkverified').onclick=e=>run(e.target,()=>refresh())}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>run(b,async()=>{view=b.dataset.view;await refresh()}));$('#search').onsubmit=e=>{e.preventDefault();area=new FormData(e.target).get('area').trim();run(e.submitter,()=>refresh())};if($('#more'))$('#more').onclick=e=>run(e.target,()=>refresh(true));
if($('#add')){$('#add').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('/orders',Object.fromEntries(new FormData(e.target)));await refresh();toast(t('تم نشر طلبك','Request created'))})};$('#locate').onclick=()=>{if(!navigator.geolocation)return toast(t('الموقع غير مدعوم','Location is unavailable'));navigator.geolocation.getCurrentPosition(p=>{$('[name="lat"]').value=p.coords.latitude.toFixed(6);$('[name="lng"]').value=p.coords.longitude.toFixed(6)},()=>toast(t('تعذر تحديد الموقع؛ أدخل الإحداثيات يدويًا','Location unavailable. Enter coordinates manually.')),{timeout:10000,maximumAge:60000})}}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='receipt')return receipt(Number(b.dataset.id));run(b,async()=>{await api(`/orders/${b.dataset.id}/${b.dataset.action}`,{});await refresh();toast(t('تم تحديث الطلب','Request updated'))})});document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>showMap(Number(b.dataset.map)))}
function dialog(html){$('#dialog').innerHTML=html;$('#dialog').showModal();$('#close').onclick=()=>$('#dialog').close()}
function closeButton(){return `<button type="button" class="ghost" id="close">${t('رجوع','Back')}</button>`}
function showMap(id){const o=orders.find(x=>x.id===id);const url=`https://www.openstreetmap.org/?mlat=${o.lat}&mlon=${o.lng}#map=17/${o.lat}/${o.lng}`;dialog(`<h2>${t('نقطة الاستلام','Pickup location')}</h2><p>${esc(o.address)}</p><p dir="ltr">${o.lat}, ${o.lng}</p><p class="small">${t('فتح الخريطة يرسل الإحداثيات إلى OpenStreetMap. الموقع اختياري ومن إدخال صاحب المحل.','Opening the map shares these coordinates with OpenStreetMap. Location is optional and supplied by the shop.')}</p><div class="actions"><a class="cta" href="${url}" target="_blank" rel="noopener noreferrer">${t('فتح الخريطة الخارجية','Open external map')}</a>${closeButton()}</div>`)}
function receipt(id){const o=orders.find(x=>x.id===id);dialog(`<form id="receipt"><h2>${t('تسجيل الاستلام','Record pickup')}</h2><p>${esc(o.name)} #${id}</p>${field(t('الوزن الفعلي / كجم','Actual weight / kg'),input('actual','number',`required min="0.1" max="5000" step="0.1" value="${o.weight}"`))}${field(t('سعر الكيلو / ج.م','Price per kg / EGP'),input('price','number','required min="0" max="10000" step="0.01"'))}<p class="small">${t('سيُرسل للمحل للمراجعة. لا يحدث تحويل أموال. الاستلام الجزئي يغلق الطلب بعد التأكيد؛ أضف طلبًا جديدًا للباقي.','The shop will review this receipt. No money is transferred. A confirmed partial pickup closes this request; create a new one for the remainder.')}</p><div class="actions"><button>${t('إرسال للتأكيد','Send for confirmation')}</button>${closeButton()}</div></form>`);$('#receipt').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api(`/orders/${id}/receipt`,Object.fromEntries(new FormData(e.target)));$('#dialog').close();await refresh()})}}
function tokenDialog(){const params=new URLSearchParams(location.hash.slice(1));const purpose=params.has('reset')?'reset':params.has('verify')?'verify':null;if(!purpose)return;const token=params.get(purpose);history.replaceState(null,'',location.pathname);dialog(`<form id="token"><h2>${purpose==='reset'?t('تعيين كلمة مرور جديدة','Set a new password'):t('تأكيد البريد الإلكتروني','Verify email')}</h2>${purpose==='reset'?field(t('كلمة المرور الجديدة','New password'),input('password','password','required minlength="10" maxlength="128" autocomplete="new-password"')):''}<div class="actions"><button>${t('تأكيد','Confirm')}</button>${closeButton()}</div></form>`);$('#token').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await api('/token/'+purpose,{token,...Object.fromEntries(new FormData(e.target))});$('#dialog').close();if(purpose==='reset'){user=null;mode='login';render();toast(t('اتغيرت كلمة المرور؛ سجل الدخول من جديد','Password changed. Sign in again.'))}else{user=(await api('/me')).user;if(user)await refresh();toast(t('تم تأكيد البريد','Email verified'))}})}}
window.addEventListener('hashchange',tokenDialog);
(async()=>{try{const me=await api('/me');user=me.user;mailMode=me.mail_mode;if(user)await refresh();else render();tokenDialog()}catch(e){render();toast(e.message)}})();
